  public async getAuthSession(tokenHash:string):Promise<AuthSession|null>{const[rows]=await this.executor.execute<RowDataPacket[]>(`SELECT s.token_hash,s.user_id,s.expires_at,u.status,MAX(st.status) staff_status,GROUP_CONCAT(ur.role) roles FROM auth_sessions s JOIN users u ON u.id=s.user_id LEFT JOIN internal_staff st ON st.user_id=s.user_id LEFT JOIN user_roles ur ON ur.user_id=s.user_id WHERE s.token_hash=? GROUP BY s.token_hash,s.user_id,s.expires_at,u.status`,[tokenHash]);const r=rows[0];if(!r||r.status!=='ACTIVE'||(r.staff_status!==null&&r.staff_status!==undefined&&r.staff_status!=='ACTIVE')||new Date(r.expires_at as Date).getTime()<=Date.now())return null;return{tokenHash:String(r.token_hash),userId:String(r.user_id),roles:String(r.roles??'USER').split(',') as Role[],expiresAt:iso(r.expires_at as Date)};}
