  public async listManualOrderNotifications(limit:number):Promise<OrderNotification[]>{const safeLimit=Math.max(1,Math.min(1000,limit));const[rows]=await this.executor.query<RowDataPacket[]>(`SELECT * FROM order_notifications WHERE status IN ('PENDING_DELIVERY','MANUAL_REQUIRED') ORDER BY created_at DESC,id DESC LIMIT ${safeLimit}`);return rows.map((row)=>this.notificationFromRow(row));}
  public async claimPendingOrderNotifications(limit:number,leaseUntil:string,now:string,claimToken:string):Promise<OrderNotification[]>{
    if (!('beginTransaction' in this.executor)) return this.transaction((store)=>store.claimPendingOrderNotifications(limit,leaseUntil,now,claimToken));
    const safeLimit=Math.max(1,Math.min(5,Math.trunc(limit)));
    const [rows]=await this.executor.query<RowDataPacket[]>(`SELECT * FROM order_notifications WHERE status='PENDING_DELIVERY' AND (next_attempt_at IS NULL OR next_attempt_at<=?) AND (delivery_lease_until IS NULL OR delivery_lease_until<=?) ORDER BY created_at,id LIMIT ${safeLimit} FOR UPDATE SKIP LOCKED`,[new Date(now),new Date(now)]);
    if(!rows.length)return [];
    const ids=rows.map((row)=>String(row.id));
    await this.executor.execute(`UPDATE order_notifications SET delivery_lease_until=?,delivery_claim_token=? WHERE id IN (${ids.map(()=>'?').join(',')})`,[new Date(leaseUntil),claimToken,...ids]);
    return rows.map((row)=>({...this.notificationFromRow(row),deliveryLeaseUntil:leaseUntil,deliveryClaimToken:claimToken}));
  }
